def transform(grid):
 h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
 seen=set()
 for r in range(h):
  for c in range(w):
   if not grid[r][c] or (r,c) in seen: continue
   color=grid[r][c]; pts=[]; stack=[(r,c)]; seen.add((r,c))
   while stack:
    a,b=stack.pop(); pts.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
      seen.add((x,y)); stack.append((x,y))
   lo=min(a for a,b in pts); hi=max(a for a,b in pts); left=min(b for a,b in pts); right=max(b for a,b in pts)
   rows={a:sum(x==a for x,y in pts) for a in range(lo,hi+1)}
   cols={b:sum(y==b for x,y in pts) for b in range(left,right+1)}
   dr=dc=0
   if rows[hi]>1 and all(rows[a]==1 for a in range(lo,hi)):
    dr=-lo
   elif rows[lo]>1 and all(rows[a]==1 for a in range(lo+1,hi+1)):
    dr=h-1-hi
   elif cols[right]>1 and all(cols[b]==1 for b in range(left,right)):
    dc=-left
   elif cols[left]>1 and all(cols[b]==1 for b in range(left+1,right+1)):
    dc=w-1-right
   for a,b in pts: out[a+dr][b+dc]=color
 return out

